const request = $input.first().json;
const body = request.body;
const ownObject = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const id = ownObject(body) && typeof body.id === 'string' && /^(?:[a-f0-9]{64}|[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12})$/i.test(body.id) ? body.id : '';
const failed = () => [{json:{id,status:'failed',httpCode:422}}];
if (request.executionMode !== 'production' || request.webhookUrl !== 'https://n8n.avilaops.com/webhook/erp-document-mail-v1' || !id || !/^application\/json(?:\s*;|$)/i.test(request.headers?.['content-type'] || '') || Object.keys(body).some(k => !['id','to','subject','text','html','attachments'].includes(k))) return failed();
const recipients = Array.isArray(body.to) ? body.to : [body.to];
const address = /^[A-Za-z0-9!#$%&'*+/=?^_\x60{|}~-]+(?:\.[A-Za-z0-9!#$%&'*+/=?^_\x60{|}~-]+)*@(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/;
if (recipients.length < 1 || recipients.length > 20 || recipients.some(v => typeof v !== 'string' || v.length > 254 || /[\s\x00-\x1f\x7f]/.test(v) || !address.test(v)) || new Set(recipients.map(v => v.toLowerCase())).size !== recipients.length) return failed();
if (typeof body.subject !== 'string' || !body.subject.trim() || body.subject.length > 256 || /[\x00-\x1f\x7f]/.test(body.subject)) return failed();
const safeBody = (v,limit) => typeof v === 'string' && Buffer.byteLength(v,'utf8') <= limit && !/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(v);
if (!safeBody(body.text, 128 * 1024) || !body.text.trim() || (body.html !== undefined && !safeBody(body.html, 512 * 1024))) return failed();
if (!Array.isArray(body.attachments) || body.attachments.length > 40) return failed();
const binary = {};
const names = new Set();
const maxBytes = 10 * 1024 * 1024;
let total = 0;
for (const [i, file] of body.attachments.entries()) {
  if (!ownObject(file) || Object.keys(file).some(k => !['filename','contentType','content'].includes(k))) return failed();
  const {filename,contentType,content} = file;
  if (typeof filename !== 'string' || filename.length > 180 || !filename.trim() || /[\/\\\x00-\x1f\x7f<>:"|?*]/.test(filename) || names.has(filename.toLowerCase())) return failed();
  if (typeof contentType !== 'string' || !/^(application\/pdf|application\/xml|text\/xml|text\/html)(?:\s*;\s*charset\s*=\s*utf-8)?$/i.test(contentType)) return failed();
  const mimeType = contentType.split(';')[0].trim().toLowerCase();
  const ext = mimeType === 'application/pdf' ? /\.pdf$/i : mimeType === 'text/html' ? /\.html?$/i : /\.xml$/i;
  if (!ext.test(filename) || typeof content !== 'string' || !content.length || content.length % 4 !== 0 || content.length > 4 * Math.ceil((maxBytes-total)/3) || !/^[A-Za-z0-9+/]+={0,2}$/.test(content)) return failed();
  const bytes = Buffer.from(content,'base64');
  total += bytes.length;
  if (total > maxBytes || bytes.toString('base64') !== content) return failed();
  names.add(filename.toLowerCase());
  binary['file'+i] = {data:content,mimeType,fileName:filename};
}
return [{json:{id,ready:true,to:recipients.join(', '),recipients,subject:body.subject,text:body.text,html:body.html || '',files:Object.keys(binary).join(',')},binary}];

const message = $('Validar documento').first().json;
const result = $input.first().json;
const addresses = v => Array.isArray(v) && v.every(a => typeof a === 'string') ? v.map(a => a.toLowerCase()) : [];
const accepted = addresses(result.accepted);
const expected = message.recipients.map(a => a.toLowerCase());
const complete = Array.isArray(result.rejected) && result.rejected.length === 0 && accepted.length === expected.length && expected.every(a => accepted.includes(a)) && /^250(?:\s|-|$)/.test(String(result.response || ''));
const explicitlyRefused = (typeof result.error === 'string' && /^Can['’]t send mail - all recipients were rejected(?:[.: ]|$)/i.test(result.error)) || (Array.isArray(result.accepted) && !result.accepted.length && Array.isArray(result.rejected) && result.rejected.length === expected.length && expected.every(a=>addresses(result.rejected).includes(a)));
return [{json:{id:message.id,status:complete ? 'sent' : explicitlyRefused ? 'failed' : 'unknown',httpCode:200}}];
